'use strict';
const config=JSON.parse(document.getElementById('config').textContent), canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),W=800,H=500,TAU=2*Math.PI;
const controls=document.getElementById('controls'),status=document.getElementById('status'),inputs={},values={};let edits=new Set();
for(const [id,label,min,max,value,step] of config.controls){const wrap=document.createElement('label'),out=document.createElement('output'),input=document.createElement('input');wrap.append(document.createTextNode(label),out,input);input.type='range';input.id=id;input.min=min;input.max=max;input.step=step;input.value=value;out.htmlFor=id;inputs[id]=input;const update=()=>{values[id]=+input.value;out.value=input.value;};update();input.addEventListener('input',()=>{update();if(config.kind==='cellular'&&(id==='density'||id==='seed'))edits.clear();draw();});controls.append(wrap);input.refresh=update;}
document.getElementById('reset').onclick=()=>{for(const [id,,, ,value]of config.controls){inputs[id].value=value;inputs[id].refresh();}edits.clear();draw();};
function line(points,color='#315d58',width=1.5,close=false){if(!points.length)return;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));if(close)ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function dot(x,y,r=3,color='#315d58'){ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fillStyle=color;ctx.fill();}
function random(seed){let s=seed>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
function hash(x,y,seed){let n=Math.imul(x,374761393)+Math.imul(y,668265263)+Math.imul(seed,1447);n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967295;}
function noise(x,y,seed){const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy,u=fx*fx*(3-2*fx),v=fy*fy*(3-2*fy),a=hash(ix,iy,seed),b=hash(ix+1,iy,seed),c=hash(ix,iy+1,seed),d=hash(ix+1,iy+1,seed);return (a+(b-a)*u)*(1-v)+(c+(d-c)*u)*v;}
function field(x,y){const dx=values.x*8-x,dy=values.y*5-y,d=Math.max(15,Math.hypot(dx,dy));let vx=values.pull*dx/d-values.swirl*dy/d+values.drift,vy=values.pull*dy/d+values.swirl*dx/d,m=Math.hypot(vx,vy);return m<1e-8?[0,0]:[vx/m,vy/m];}
function draw(){ctx.clearRect(0,0,W,H);status.textContent='';const v=values;
switch(config.kind){
case 'waves':for(let row=0;row<v.rows;row++){const base=H*(row+1)/(v.rows+1),pts=[];for(let x=20;x<=780;x+=2)pts.push([x,base+v.amplitude*Math.sin(TAU*v.frequency*(x-20)/760+v.phase+row*.3)]);line(pts,row%2?'#bb6232':'#315d58',2);}break;
case 'phyllotaxis':for(let n=0;n<v.count;n++){const a=n*v.angle*Math.PI/180,r=210*(v.spread/100)*Math.sqrt(n/v.count);dot(W/2+r*Math.cos(a),H/2+r*Math.sin(a),v.size,n%13===0?'#bb6232':'#315d58');}status.textContent=`${v.count} points · angle ${v.angle}°`;break;
case 'noise':{const step=720/(v.density-1),rows=Math.floor(420/step)+1;for(let j=0;j<rows;j++)for(let i=0;i<v.density;i++){const x=40+i*step,y=40+j*step,dx=(noise(i/v.density*v.scale,j/v.density*v.scale,v.seed)-.5)*v.strength*2,dy=(noise(i/v.density*v.scale+21,j/v.density*v.scale+31,v.seed)-.5)*v.strength*2;line([[x,y],[x+dx,y+dy]],'#aab6ab',1);dot(x+dx,y+dy,2.6);}break;}
case 'cellular':{const n=v.density,size=760/n,rows=Math.floor(460/size),rng=random(v.seed);let cells=Array.from({length:n},(_,i)=>v.seed===0?+(i===Math.floor(n/2)):+(rng()<.4));for(const i of edits)if(i<n)cells[i]=1-cells[i];for(let j=0;j<rows;j++){for(let i=0;i<n;i++)if(cells[i]){ctx.fillStyle=j===0?'#bb6232':'#315d58';ctx.fillRect(20+i*size,20+j*size,Math.max(.5,size-.5),Math.max(.5,size-.5));}cells=cells.map((_,i)=>(v.rule>>((cells[(i+n-1)%n]<<2)|(cells[i]<<1)|cells[(i+1)%n]))&1);}status.textContent=`Rule ${v.rule} · ${n} columns · ${rows} generations · click the top row to toggle a seed cell`;break;}
case 'vectors':{const step=740/v.density;for(let y=30;y<480;y+=step)for(let x=30;x<780;x+=step){const [vx,vy]=field(x,y),len=step*.33,ex=x+vx*len,ey=y+vy*len;line([[x-vx*len/2,y-vy*len/2],[ex,ey]],'#315d58',1.5);line([[ex-vx*5-vy*3,ey-vy*5+vx*3],[ex,ey],[ex-vx*5+vy*3,ey-vy*5-vx*3]],'#315d58',1.5);}for(let y=25;y<500;y+=35){let x=10,yy=y,pts=[];for(let s=0;s<320;s++){pts.push([x,yy]);const [vx,vy]=field(x,yy);x+=vx*2;yy+=vy*2;if(x<0||x>W||yy<0||yy>H)break;}line(pts,'#bb6232',1);}dot(v.x*8,v.y*5,7,'#bb6232');status.textContent='Drag anywhere in the field to move its center.';break;}
case 'accumulation':{const rng=random(v.seed);let tips=[{x:400,y:475,a:-Math.PI/2}],count=0;for(let s=0;s<v.steps&&count<4000;s++){const next=[];for(const tip of tips){if(count>=4000)break;const a=tip.a+(rng()-.5)*.16,x=tip.x+Math.cos(a)*v.length,y=tip.y+Math.sin(a)*v.length;if(x<12||x>788||y<12||y>488)continue;line([[tip.x,tip.y],[x,y]],s>v.steps*.7?'#bb6232':'#315d58',Math.max(1,3-s*.04));count++;if(rng()<v.branch/100){const turn=v.angle*Math.PI/180;next.push({x,y,a:a-turn},{x,y,a:a+turn});}else next.push({x,y,a});}tips=next;}status.textContent=`${count.toLocaleString()} segments${count>=4000?' · segment limit reached':''}`;break;}
case 'curve-distribution':{const a=300,b=200*v.aspect/100,table=[0],sample=1000;let total=0,prev=[a,0];for(let i=1;i<=sample;i++){const t=TAU*i/sample,p=[a*Math.cos(t),b*Math.sin(t)];total+=Math.hypot(p[0]-prev[0],p[1]-prev[1]);table.push(total);prev=p;}const outline=[];for(let i=0;i<=sample;i+=4){const t=TAU*i/sample;outline.push([400+a*Math.cos(t),250+b*Math.sin(t)]);}line(outline,'#a9b6aa',1);for(let n=0;n<v.count;n++){let t=TAU*n/v.count;if(v.spacing===0){const target=total*n/v.count;let j=1;while(j<sample&&table[j]<target)j++;t=TAU*(j-1+(target-table[j-1])/(table[j]-table[j-1]))/sample;}const x=400+a*Math.cos(t),y=250+b*Math.sin(t),angle=Math.atan2(b*Math.cos(t),-a*Math.sin(t))+v.rotation*Math.PI/180;const pts=[[-v.size/2,-4],[v.size/2,-4],[v.size/2,4],[-v.size/2,4]].map(([u,w])=>[x+u*Math.cos(angle)-w*Math.sin(angle),y+u*Math.sin(angle)+w*Math.cos(angle)]);line(pts,n%2?'#bb6232':'#315d58',2,true);}status.textContent=`${v.count} elements · ${v.spacing?'equal parameter':'approximately equal distance'} spacing`;break;}
case 'tiling':{const r=v.size,hex=v.sides===6,dx=hex?1.5*r:Math.SQRT2*r,dy=hex?Math.sqrt(3)*r:Math.SQRT2*r,theta=v.rotation*Math.PI/180;ctx.save();ctx.beginPath();ctx.rect(20,20,760,460);ctx.clip();for(let col=-25;col<=25;col++)for(let row=-25;row<=25;row++){const x=col*dx,y=(row+(hex&&Math.abs(col)%2?.5:0))*dy,alt=(col+row)%2!==0,rr=r*(1-v.gap/100)*(alt?v.alternate/100:1),pts=[];for(let k=0;k<v.sides;k++){const a=TAU*k/v.sides+(hex?0:Math.PI/4),xx=x+rr*Math.cos(a),yy=y+rr*Math.sin(a);pts.push([400+xx*Math.cos(theta)-yy*Math.sin(theta),250+xx*Math.sin(theta)+yy*Math.cos(theta)]);}line(pts,alt?'#bb6232':'#315d58',1.4,true);}ctx.restore();status.textContent=`${hex?'Hexagonal':'Square'} modules · ${v.gap}% gap · alternate size ${v.alternate}%`;break;}
case 'deformation':{const bend=v.bend*Math.PI/180,twist=v.twist*Math.PI/180,view=v.view*Math.PI/180,project=(u,w)=>{let x=300*u,y=75*w*((v.startWidth??100)/100+((v.endWidth??v.taper??65)-(v.startWidth??100))/100*(u+1)/2),z=0;function turn(){const a=twist*u/2,yy=y*Math.cos(a)-z*Math.sin(a);z=y*Math.sin(a)+z*Math.cos(a);y=yy;}function curve(){if(Math.abs(bend)<1e-8)return;const radius=600/bend,a=x/radius,old=z;x=(radius-old)*Math.sin(a);z=radius-(radius-old)*Math.cos(a);}if(v.order===0){turn();curve();}else{curve();turn();}const xx=x*Math.cos(view)+z*Math.sin(view),zz=-x*Math.sin(view)+z*Math.cos(view);return[400+xx*.85,310+y*.75-zz*.55];};for(let j=0;j<=10;j++){const pts=[];for(let i=0;i<=60;i++)pts.push(project(-1+2*i/60,-1+2*j/10));line(pts,j===0||j===10?'#bb6232':'#315d58',j===0||j===10?2:1);}for(let i=0;i<=30;i++){const pts=[];for(let j=0;j<=20;j++)pts.push(project(-1+2*i/30,-1+2*j/20));line(pts,'#315d58',1);}status.textContent=v.order?'Taper → Bend → Twist':'Taper → Twist → Bend';break;}
case 'scatter':{const names=['circle','rectangle','triangle'],boundary=v.boundary,polygon=boundary===1?[[100,60],[700,60],[700,440],[100,440]]:[[400,35],[735,455],[65,455]],inside=(x,y,margin=0)=>{if(boundary===0)return Math.hypot(x-400,y-250)<=210-margin;if(boundary===1)return x>=100+margin&&x<=700-margin&&y>=60+margin&&y<=440-margin;for(let i=0;i<3;i++){const a=polygon[i],b=polygon[(i+1)%3];if(((b[0]-a[0])*(y-a[1])-(b[1]-a[1])*(x-a[0]))/Math.hypot(b[0]-a[0],b[1]-a[1])<margin)return false;}return true;};if(boundary===0){ctx.beginPath();ctx.arc(400,250,210,0,TAU);ctx.strokeStyle='#9aa99b';ctx.lineWidth=1.5;ctx.stroke();}else line(polygon,'#9aa99b',1.5,true);let placed=0;for(let i=0;i<v.count;i++){const rng=random(Math.floor(hash(i,v.seed,37)*4294967295)),r=v.size*(1+(rng()*2-1)*v.variation/100),a=(rng()*2-1)*v.rotation*Math.PI/180;let x,y,pts,found=false;for(let attempt=0;attempt<500;attempt++){if(boundary===0){const theta=rng()*TAU,radius=210*Math.sqrt(rng());x=400+radius*Math.cos(theta);y=250+radius*Math.sin(theta);}else if(boundary===1){x=100+600*rng();y=60+380*rng();}else{let u=rng(),w=rng();if(u+w>1){u=1-u;w=1-w;}x=polygon[0][0]+u*(polygon[1][0]-polygon[0][0])+w*(polygon[2][0]-polygon[0][0]);y=polygon[0][1]+u*(polygon[1][1]-polygon[0][1])+w*(polygon[2][1]-polygon[0][1]);}const local=v.module===1?[[-r,-r*.28],[r,-r*.28],[r,r*.28],[-r,r*.28]]:Array.from({length:3},(_,k)=>[r*Math.cos(TAU*k/3-Math.PI/2),r*Math.sin(TAU*k/3-Math.PI/2)]);pts=local.map(([u,w])=>[x+u*Math.cos(a)-w*Math.sin(a),y+u*Math.sin(a)+w*Math.cos(a)]);if(v.module===0?inside(x,y,r):pts.every(([xx,yy])=>inside(xx,yy))){found=true;break;}}if(!found)continue;const color=i%5===0?'#bb6232':'#315d58';if(v.module===0)dot(x,y,r,color);else{ctx.beginPath();pts.forEach(([xx,yy],k)=>k?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy));ctx.closePath();ctx.fillStyle=color;ctx.fill();}placed++;}status.textContent=`${placed} elements inside a ${names[boundary]} · overlaps allowed · seed ${v.seed}`;break;}
case 'morphing':{const ring=[],star=[],blend=[],twist=v.twist*Math.PI/180,t=v.blend/100;for(let i=0;i<360;i++){const a=TAU*i/360-Math.PI/2,phase=((i/360*v.lobes)%1)*2,r=190*(1-v.depth/100*(phase<1?phase:2-phase)),c=[400+190*Math.cos(a),250+190*Math.sin(a)],s=[400+r*Math.cos(a+twist),250+r*Math.sin(a+twist)];ring.push(c);star.push(s);blend.push([c[0]*(1-t)+s[0]*t,c[1]*(1-t)+s[1]*t]);}ctx.setLineDash([4,5]);line(ring,'#b5c0b5',1,true);line(star,'#cbb6a6',1,true);ctx.setLineDash([]);ctx.beginPath();blend.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle='#315d5822';ctx.fill();line(blend,'#315d58',2.5,true);for(let i=0;i<360;i+=12)dot(...blend[i],2.5,'#bb6232');status.textContent=`${v.blend}% blend · dashed outlines show the two source curves`;break;}
}}
function pointer(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;if(config.kind==='vectors'){for(const [id,value]of [['x',x/8],['y',y/5]]){inputs[id].value=Math.max(0,Math.min(100,value));inputs[id].refresh();}draw();}else if(config.kind==='cellular'&&y>=20&&y<20+760/values.density&&x>=20&&x<780){const i=Math.floor((x-20)/(760/values.density));edits.has(i)?edits.delete(i):edits.add(i);draw();}}
canvas.addEventListener('pointerdown',e=>{if(config.kind==='vectors')canvas.setPointerCapture(e.pointerId);pointer(e);});canvas.addEventListener('pointermove',e=>{if(canvas.hasPointerCapture(e.pointerId))pointer(e);});draw();
